// ── New York City (MTA) adapter ──────────────────────────────────────
// One metro region: subway + Staten Island Railway, LIRR and Metro-North,
// keyless GTFS-Realtime. Buses (Bus Time, key required) are deferred.
// NJ Transit, PATH, AirTrain and NY Waterway are out of scope.
//
// Station/route/pattern data is generated by scripts/build-nyc-data.mjs into
// nyc-data.js (a classic script, so the page works from file://). Rail ids are
// namespaced ("LIRR:1", "MNR:46") because the raw numeric ids collide with the
// subway's station/route numbers.
(function () {
    "use strict";
    const D = window.MTA_NYC_DATA || { routes: {}, stations: {}, platform: {}, patterns: {} };
    const BASE = "https://api-endpoint.mta.info/Dataservice/mtagtfsfeeds/";
    const LIRR = "LIRR:";
    const MNR = "MNR:";

    // GTFS-RT feed per line, verified against the live feeds: the groups do
    // not follow the printed bullets (B rides with A/C/E, GS with 1-7, …).
    const FEED_BY_LINE = {
        "1": "nyct%2Fgtfs", "2": "nyct%2Fgtfs", "3": "nyct%2Fgtfs",
        "4": "nyct%2Fgtfs", "5": "nyct%2Fgtfs", "6": "nyct%2Fgtfs",
        "7": "nyct%2Fgtfs", "6X": "nyct%2Fgtfs", "7X": "nyct%2Fgtfs",
        GS: "nyct%2Fgtfs",
        A: "nyct%2Fgtfs-ace", B: "nyct%2Fgtfs-ace", C: "nyct%2Fgtfs-ace",
        E: "nyct%2Fgtfs-ace", H: "nyct%2Fgtfs-ace",
        D: "nyct%2Fgtfs-bdfm", F: "nyct%2Fgtfs-bdfm", FX: "nyct%2Fgtfs-bdfm",
        FS: "nyct%2Fgtfs-bdfm", M: "nyct%2Fgtfs-bdfm",
        G: "nyct%2Fgtfs-g",
        J: "nyct%2Fgtfs-jz", Z: "nyct%2Fgtfs-jz",
        L: "nyct%2Fgtfs-l",
        N: "nyct%2Fgtfs-nqrw", Q: "nyct%2Fgtfs-nqrw",
        R: "nyct%2Fgtfs-nqrw", W: "nyct%2Fgtfs-nqrw",
        SI: "nyct%2Fgtfs-si",
    };

    // One feed serves several stations, so share it instead of refetching on
    // every board tick (the page refreshes every 30 s; the feed updates ~30 s).
    const FEED_TTL_MS = 45000;
    const feedCache = new Map();      // feed id → { at, trips }
    const feedInflight = new Map();
    const past = new Map();           // feed id → last known trips on failure

    function feedOf(line) {
        const id = String(line || "");
        if (id.startsWith(LIRR)) return "lirr%2Fgtfs-lirr";
        if (id.startsWith(MNR)) return "mnr%2Fgtfs-mnr";
        return FEED_BY_LINE[id] || null;
    }

    function isRailLine(line) {
        const id = String(line || "");
        return id.startsWith(LIRR) || id.startsWith(MNR);
    }

    // The feed speaks raw route/stop ids; the data is namespaced per agency.
    function rawRoute(line) {
        const id = String(line || "");
        return isRailLine(id) ? id.slice(id.indexOf(":") + 1) : id;
    }

    function stopKey(line, stopId) {
        const id = String(line || "");
        if (!isRailLine(id)) return String(stopId);
        return id.slice(0, id.indexOf(":") + 1) + String(stopId);
    }

    async function loadFeed(feed) {
        const hit = feedCache.get(feed);
        if (hit && Date.now() - hit.at < FEED_TTL_MS) return hit.trips;
        if (feedInflight.has(feed)) return feedInflight.get(feed);
        const load = (async () => {
            const { data, error } = await MTA.http.get({
                url: BASE + feed,
                responseType: "arraybuffer",
                timeoutMs: 15000,
                retries: 1,
                memoize: false,
            });
            if (error) throw error;
            if (!data || !data.length) throw new Error("empty feed");
            const trips = MTA.gtfsrt.parse(data).trips;
            feedCache.set(feed, { at: Date.now(), trips });
            past.set(feed, trips);
            return trips;
        })().finally(() => feedInflight.delete(feed));
        feedInflight.set(feed, load);
        return load;
    }

    // NYC bbox: Manhattan + the four outer boroughs. Stations outside it are
    // still searchable (through-running LIRR/Metro-North) but flagged.
    const NYC_BBOX = { south: 40.477, north: 40.917, west: -74.26, east: -73.70 };
    function outsideNYC(lat, lon) {
        return lat < NYC_BBOX.south || lat > NYC_BBOX.north ||
            lon < NYC_BBOX.west || lon > NYC_BBOX.east;
    }

    function stationOf(code) {
        const s = D.stations[String(code)];
        return s ? {
            Code: String(code), Name: s[0], Lat: s[1], Lon: s[2],
            Lines: s[3].slice(), Outside: outsideNYC(s[1], s[2]),
        } : null;
    }

    function metroStations() {
        return Object.keys(D.stations).map(stationOf).filter(Boolean);
    }

    function metroRoutes() {
        const map = {};
        for (const [id, r] of Object.entries(D.routes))
            map[id] = { name: lineName(id), color: r[1] };
        return map;
    }

    // Express variants run under their own route_id but carry the parent
    // bullet (F express is still an F train to riders). Prefixed rail ids keep
    // their generated display name.
    function lineName(id) {
        const raw = String(id || "");
        if (raw === "FX") return "F";
        if (raw === "6X") return "6";
        if (raw === "7X") return "7";
        const r = D.routes[raw];
        return r ? r[0] : raw;
    }

    function metroColor(id) {
        const r = D.routes[String(id || "")];
        return r ? r[1] : "#5d4037";
    }

    function textOn(hex) {
        const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ""));
        if (!m) return "#fff";
        const v = parseInt(m[1], 16);
        const lin = c => {
            c /= 255;
            return c <= .03928 ? c / 12.92 : Math.pow((c + .055) / 1.055, 2.4);
        };
        const L = .2126 * lin(v >> 16 & 255) + .7152 * lin(v >> 8 & 255)
            + .0722 * lin(v & 255);
        return L > .19 ? "#111" : "#fff";
    }

    function parentOf(stopId) {
        return D.platform[stopId] || null;
    }

    // The feed lists only the remaining stops, so its tail is the terminus —
    // that name is the headsign, no static trip table needed.
    function headsignOf(trip, line) {
        for (let i = trip.stops.length - 1; i >= 0; i--) {
            const s = trip.stops[i];
            if (s.skipped) continue;
            const key = stopKey(line, s.stopId);
            const station = D.stations[parentOf(key) || key];
            return station ? station[0] : String(s.stopId);
        }
        return "";
    }

    function terminatesHere(trip, code, line) {
        for (let i = trip.stops.length - 1; i >= 0; i--) {
            const s = trip.stops[i];
            if (s.skipped) continue;
            return parentOf(stopKey(line, s.stopId)) === String(code);
        }
        return false;
    }

    async function metroLive(codes) {
        const list = [...new Set((codes || []).map(String).filter(Boolean))];
        const out = {};
        for (const c of list) out[c] = [];
        if (!list.length) return out;

        const feeds = new Set();
        for (const c of list) {
            const st = D.stations[c];
            for (const line of (st && st[3]) || []) {
                const feed = feedOf(line);
                if (feed) feeds.add(feed);
            }
        }

        const tripsByFeed = new Map();
        const failed = new Set();
        await Promise.all([...feeds].map(async feed => {
            try {
                tripsByFeed.set(feed, await loadFeed(feed));
            } catch (e) {
                failed.add(feed);
                // A stale refresh is better than an empty board.
                if (past.has(feed)) tripsByFeed.set(feed, past.get(feed));
            }
        }));
        if (feeds.size && failed.size === feeds.size && !tripsByFeed.size)
            throw new Error("MTA feed unavailable");

        const now = Date.now();
        for (const c of list) {
            const st = D.stations[c];
            if (!st) continue;
            const lines = new Set(st[3]);
            const seen = new Set();
            for (const line of lines) {
                const feed = feedOf(line);
                const trips = feed && tripsByFeed.get(feed);
                if (!trips) continue;
                for (const trip of trips) {
                    if (trip.routeId !== rawRoute(line)) continue;
                    if (seen.has(trip.tripId)) continue;
                    let stop = null;
                    for (const s of trip.stops) {
                        if (s.skipped || s.at == null) continue;
                        if (parentOf(stopKey(line, s.stopId)) === c) { stop = s; break; }
                    }
                    if (!stop || stop.at < now - 60000) continue;
                    if (terminatesHere(trip, c, line)) continue;
                    seen.add(trip.tripId);
                    const heads = headsignOf(trip, line);
                    out[c].push({
                        min: Math.max(0, Math.round((stop.at - now) / 60000)),
                        at: stop.at,
                        route: line,
                        routeRef: line,
                        dir: heads,
                        heads,
                        dirNum: String(trip.directionId || 0),
                        vehicle: null,
                        trip: trip.tripId,
                        status: stop.at - now < 60000 ? "Arriving" : "",
                        etaAt: stop.at,
                        observedAt: now,
                    });
                }
            }
            out[c].sort((a, b) => a.min - b.min || a.route.localeCompare(b.route));
        }
        return out;
    }

    // Buses are a later phase (MTA Bus Time needs a key); these keep the bus
    // code paths inert instead of throwing.
    async function nearbyStops() { return []; }
    async function allStops() { return []; }
    async function departures(stopIds) {
        const out = new Map();
        for (const id of stopIds || [])
            out.set(String(id), { name: "", predictions: [] });
        return out;
    }
    async function stopSchedule() { return []; }
    async function busRouteDirectory() { return []; }
    async function stopsForRoute() { return []; }
    async function place(id) {
        const st = stationOf(id);
        return st ? { id: st.Code, name: st.Name, lat: st.Lat, lon: st.Lon } : null;
    }

    function connections(kind, id) {
        const out = { bus: [], metro: [], places: {} };
        if (kind === "metro") {
            const st = stationOf(id);
            if (st) {
                out.metro = st.Lines.slice();
                for (const line of out.metro)
                    out.places["metro:" + String(line).toUpperCase()] =
                        { stopId: st.Code, name: st.Name };
            }
        }
        return out;
    }

    function resetCaches() {
        feedCache.clear();
        past.clear();
        feedInflight.clear();
    }

    // "Next stops…" for a trip: pick the stored pattern that contains both the
    // boarding station and the destination, and return the slice between them
    // (reversed when the pattern runs the other way).
    async function metroPath(from, to, line) {
        const seqs = (D.patterns && D.patterns[String(line || "")]) || [];
        const a = String(from || ""), b = String(to || "");
        if (!a || !b || a === b) return [];
        for (const seq of seqs) {
            const i = seq.indexOf(a), j = seq.indexOf(b);
            if (i < 0 || j < 0 || i === j) continue;
            const lo = Math.min(i, j), hi = Math.max(i, j);
            let ids = seq.slice(lo, hi + 1);
            if (i > j) ids = ids.slice().reverse();
            return ids.map(id => {
                const st = D.stations[id];
                return { StationCode: id, StationName: st ? st[0] : id };
            });
        }
        return [];
    }

    function isCommuter(line) { return isRailLine(line); }

    MTA.registerCity({
        id: "nyc",
        name: "New York City",
        agency: "MTA",
        locale: "en-US",
        timezone: "America/New_York",
        center: { lat: 40.7580, lon: -73.9855 },        // Times Sq-42 St
        metroCenter: { lat: 40.7580, lon: -73.9855 },
        nearbyLabel: "New York City",
        nearbyByDefault: true,
        storageKey: "nyc",
        defaultStopId: "127",
        defaultLike: { kind: "metro", id: "127", name: "Times Sq-42 St", route: "1" },
        airportDefaults: {
            // LGA has no rail link (M60-SBS from Terminal B); JFK is the A to
            // Howard Beach or the LIRR to Jamaica (AirTrain is out of scope).
            // Bus Time is a later phase, so the LGA card shows no live
            // arrivals until then.
            bus: [{ id: "904417", name: "LGA/Terminal B", route: "M60" }],
            metro: [
                { id: "H03", name: "Howard Beach-JFK Airport", route: "A" },
                { id: "LIRR:102", name: "Jamaica", route: "LIRR:12" },
            ],
        },
        labels: {
            nextBus: "Next bus", nextTrain: "Next train",
            stop: "stop", station: "station", towards: "towards", platform: "Platform",
            railNoun: "train",
        },
        capabilities: {
            bus: false,                 // MTA Bus Time is a later phase
            batchDepartures: false,
            scheduleFallback: false,
            patterns: false,
            rail: true,
            railPath: true,
            metroRoutes: true,
            metroGtfs: false,
            vehicles: false,
            routeStopsOnDemand: false,
            stopSearch: false,
            routeSearchByStop: false,
            preloadBookmarks: false,
            routeColorsFromDirectory: false,
        },
        provider: {
            http: async () => ({ data: null, error: new Error("nyc: no bus API yet") }),
            nearbyStops, allStops, departures, stopSchedule, routeDetails: async () => null,
            metroStations, metroRoutes, metroLive, metroPath,
            busRouteDirectory, stopsForRoute,
            place, connections, connectionsReady: () => true, resetCaches,
        },
        theme: {
            icons: "nyc",
            cssVars: {
                "--city-accent": "#181A7B",
                "--badge-radius": "4px",
                "--hero-bus-bg": "#e6ecf7",
                "--hero-bus-color": "#0A1438",
                "--hero-metro-bg": "#e6ecf7",
                "--hero-metro-color": "#0A1438",
            },
            routeColor: () => "#181A7B",
            routeTextColor: () => "#fff",
            badgeClass: () => "",
            badge: {
                // Commuter services are named rectangles; subway locals are
                // circles and express variants diamonds.
                shape: id => isCommuter(id) ? "rect"
                    : /X$/.test(String(id || "")) ? "diamond" : "circle",
                color: id => metroColor(id),
                textColor: id => textOn(metroColor(id)),
            },
            metroColor,
            metroName: lineName,
            isCommuter,
            metroLineIds: () => Object.keys(D.routes),
        },
    });
})();
